insert into studies (id, code, name, sponsor, phase, type, species, status, enrollment_target, description) values
  ('20000000-0000-0000-0000-000000002401','PH-2401','Phytogenic Feed Additive Broiler Growth Performance Trial','PhytoNutra Animal Health','Phase III','livestock_group','chicken','active',20,'Randomized complete block — 20 broiler pens (30 birds/pen) in a single controlled-environment house; 2 arms (T01 Control, T02 Phytogenic 0.05% blend); 42 days; pen-level capture, house-level Daily Environmental Log. Primary endpoints FCR / ADG / final body weight · Protocol PHY-2025-001'),
  ('20000000-0000-0000-0000-000000002502','BR-2502','Bovine Respiratory Disease Treatment Trial','BoviPharm Therapeutics','Phase III','livestock_individual','cattle','active',270,'Randomized, masked, 3-arm — 270 feedlot cattle across 4 sites; rolling enrollment; individual-animal capture. Heart-rate validation is age-class–specific (calf ≤6 mo 100–140 bpm vs adult 48–84 bpm) · Protocol BR-2502'),
  ('20000000-0000-0000-0000-000000000801','CA-0801','DermAlliv™ Canine Atopic Dermatitis Study','DermAlliv Therapeutics','Phase III','companion','canine','active',60,'Randomized, double-blind, placebo-controlled, multi-site (3 sites) — canine atopic dermatitis · Protocol DERM-2026-104');
