insert into queries (id, form_instance_id, field_value_id, status, severity, title, raised_by, raised_at) values
  ('70000001-0000-0000-0000-000000002401','63000008-0000-0000-0000-000000002401','64000052-0000-0000-0000-000000002401','open','minor','Wet litter — welfare follow-up','10000000-0000-0000-0000-000000000001',now()),
  ('70000002-0000-0000-0000-000000002401','6300000F-0000-0000-0000-000000002401','64000098-0000-0000-0000-000000002401','open','major','Computed period FCR is above the broiler performance range (1.50–1.80; soft alert above 1.90) — verify the pen weight and feed weigh-back entries and investigate feed wastage or sub-optimal flock health.','10000000-0000-0000-0000-000000000001',now()),
  ('70000001-0000-0000-0000-000000002502','63000003-0000-0000-0000-000000002502','64000017-0000-0000-0000-000000002502','open','major','Rectal temperature 40.6 °C exceeds the bovine range (38.0–39.3 °C) — consistent with a febrile BRD episode; confirm against source and the screening reading. (Heart rate 120 bpm is also above the adult range 48–84 bpm for this 14-month animal.)','10000000-0000-0000-0000-000000000001',now()),
  ('70000002-0000-0000-0000-000000002502','63000009-0000-0000-0000-000000002502','64000051-0000-0000-0000-000000002502','responded','minor','Dosing weight vs arrival weight','10000000-0000-0000-0000-000000000001',now()),
  ('70000001-0000-0000-0000-000000000801','63000009-0000-0000-0000-000000000801','64000037-0000-0000-0000-000000000801','open','minor','Baseline PVAS vs owner diary','10000000-0000-0000-0000-000000000001',now()),
  ('70000002-0000-0000-0000-000000000801','6300000F-0000-0000-0000-000000000801','64000061-0000-0000-0000-000000000801','responded','minor','Screening weight vs referral record','10000000-0000-0000-0000-000000000001',now()),
  ('70000003-0000-0000-0000-000000000801','6300003D-0000-0000-0000-000000000801','640000B6-0000-0000-0000-000000000801','open','minor','CADESI-04 score vs lesion photos','10000000-0000-0000-0000-000000000001',now()),
  ('70000004-0000-0000-0000-000000000801','63000040-0000-0000-0000-000000000801','640000C8-0000-0000-0000-000000000801','open','major','Temperature 40.1 °C is above the expected range for dogs (38.3–39.2 °C) — verify the thermometer and re-check the patient for pyrexia.','10000000-0000-0000-0000-000000000001',now());
insert into query_messages (id, query_id, author_id, body) values
  ('71000001-0000-0000-0000-000000002401','70000001-0000-0000-0000-000000002401','10000000-0000-0000-0000-000000000001','Litter moisture recorded as Wet with caking present at D14. Wet litter raises footpad-dermatitis and ammonia risk — confirm the reading, check for drinker leaks, and document the corrective action.'),
  ('71000002-0000-0000-0000-000000002401','70000002-0000-0000-0000-000000002401','10000000-0000-0000-0000-000000000001','Auto edit-check: Computed period FCR is above the broiler performance range (1.50–1.80; soft alert above 1.90) — verify the pen weight and feed weigh-back entries and investigate feed wastage or sub-optimal flock health.'),
  ('71000001-0000-0000-0000-000000002502','70000001-0000-0000-0000-000000002502','10000000-0000-0000-0000-000000000001','Auto edit-check: Rectal temperature 40.6 °C exceeds the bovine range (38.0–39.3 °C) — consistent with a febrile BRD episode; confirm against source and the screening reading. (Heart rate 120 bpm is also above the adult range 48–84 bpm for this 14-month animal.)'),
  ('71000002-0000-0000-0000-000000002502','70000002-0000-0000-0000-000000002502','10000000-0000-0000-0000-000000000001','Body weight at dosing (278 kg) differs from the arrival weight (272 kg) on the manifest by more than 5 kg. Confirm the chute scale reading used for the dose calculation.'),
  ('71000003-0000-0000-0000-000000002502','70000002-0000-0000-0000-000000002502','10000000-0000-0000-0000-000000000001','Re-verified at the chute — 278 kg is correct; the manifest carried an estimated arrival weight. Dose volume recalculated and unchanged.'),
  ('71000001-0000-0000-0000-000000000801','70000001-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Baseline owner PVAS of 7.2 is higher than the average of the pre-baseline diary entries (≈5.8). Please confirm the score was transcribed from the correct diary week.'),
  ('71000002-0000-0000-0000-000000000801','70000002-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Screening weight 31.2 kg differs from the referral record (29.4 kg). Confirm the scale reading and recent weight history.'),
  ('71000003-0000-0000-0000-000000000801','70000002-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Re-weighed on a calibrated scale at 31.2 kg; owner reports recent weight gain on the current diet. Value confirmed.'),
  ('71000004-0000-0000-0000-000000000801','70000003-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','CADESI-04 recorded as 22 but the uploaded lesion photographs suggest more extensive truncal involvement. Please re-score against the photo set and confirm.'),
  ('71000005-0000-0000-0000-000000000801','70000004-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Auto edit-check: Temperature 40.1 °C is above the expected range for dogs (38.3–39.2 °C) — verify the thermometer and re-check the patient for pyrexia.');
